enum Command: Codable {
    case reserveStock(orderId: String, qty: Int)
    case cancelOrder(orderId: String)
}

func handle(_ command: Command) {
    switch command {
    case let .reserveStock(orderId, qty): stock.reserve(orderId, qty)
    case let .cancelOrder(orderId): stock.cancel(orderId)
    }
}
